1688	\begin{lemma}[Replacing the combined point measurement by the ordered product]
1689		\label{lem:claim-17-1}
1690		\notready
1691		% claim:17-1 in the paper; the original label is recorded here as a
1692		% comment for cross-reference fidelity.
1693		\uses{lem:qld-sublines, lem:qld-xz-lines, lem:qld-4-10,
1694			def:expanded-point-measurement, def:expanded-state}
1695		\begin{align*}
1696			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
1697			\E_{(x,z,\alpha,\beta) \in \ell}
1698			&\sum_{f_X,f_Z} \bra{\hat\psi}
1699			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1700			\big(\hat{Q}^{x,z}_{f_X(x),f_Z(z)}\big)_{\mathsf{B}\mathsf{A}''}
1701			\ket{\hat\psi} \\
1702			\approx_{\delta_Q^{1/2}}\
1703			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
1704			\E_{(x,z,\alpha,\beta) \in \ell}
1705			&\sum_{f_X,f_Z} \bra{\hat\psi}
1706			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1707			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)} \,
1708			\hat{M}^{(\mathrm{Point},X),x}_{f_X(x)}
1709			\big)_{\mathsf{B}\mathsf{A}''}
1710			\ket{\hat\psi}\,.
1711		\end{align*}
1712	\end{lemma}
1713	\begin{proof}
1714		\uses{lem:qld-4-10, lem:qld-4-10-same-placement, lem:qld-sublines,
1715			lem:qld-xz-lines, def:line-point-dist}
1716		Write
1717		$W^{x,z}_{a,b} = \hat{Q}^{x,z}_{a,b}
1718		- \hat{M}^{(\mathrm{Point},Z),z}_{b}
1719		\hat{M}^{(\mathrm{Point},X),x}_{a}$
1720		and apply the Cauchy--Schwarz inequality to the difference of the two
1721		sides. The first factor is at most $1$ because
1722		$\sum_{f_X,f_Z \,:\, f_X(x)=a,\ f_Z(z)=b}
1723		T^{\ell_X,\ell_Z}_{f_X,f_Z} \le \Id$
1724		for every $x, z, a, b$. For the second factor, note that when $\ell$ is
1725		drawn from the line-point distribution over $\F_q^{2m+2}$, a uniformly
1726		random point $(x,z,\alpha,\beta)$ on $\ell$ is a uniformly random point
1727		of $\F_q^{2m+2}$, so the coordinates $x, z$ are independent and uniform
1728		in $\F_q^m$; hence
1729		$\E_{x,z} \sum_{a,b}
1730		\bra{\hat\psi} \Id \ot (W^{x,z}_{a,b})^\dagger W^{x,z}_{a,b}
1731		\ket{\hat\psi} \le 4\delta_Q$
1732		by Lemma~\ref{lem:qld-4-10-same-placement}. The total error is
1733		therefore at most $2\sqrt{\delta_Q}$, with the same asymptotic order
1734		as the source claim. The adjoint is necessary because the ordered
1735		product need not be Hermitian. This source proof still requires the
1736		seed-indexed distribution and a complex modulus estimate; the proved
1737		real-part estimate on the auxiliary distribution is stated separately
1738		below. See \cite{gap:qpbt_ld-dimension-divisibility}.
1739	\end{proof}
