1741	\begin{lemma}[Removing the $X$-point factor]
1742		\label{lem:claim-17-2}
1743		\lean{MIPStarRE.QPBT.subline_remove_X_factor}
1744		\notready
1745		% claim:17-2 in the paper; the original label is recorded here as a
1746		% comment for cross-reference fidelity. The source right-hand side
1747		% carries a typographical superscript "Z" in place of the point "z";
1748		% the corrected form is stated here.
1749		\uses{lem:qld-sublines, lem:qld-xz-lines,
1750			def:expanded-point-measurement, lem:qld-comm-line-cons,
1751			def:expanded-state}
1752		\begin{align*}
1753			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
1754			\E_{(x,z,\alpha,\beta) \in \ell}
1755			&\sum_{f_X,f_Z} \bra{\hat\psi}
1756			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1757			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)} \,
1758			\hat{M}^{(\mathrm{Point},X),x}_{f_X(x)}
1759			\big)_{\mathsf{B}\mathsf{A}''}
1760			\ket{\hat\psi} \\
1761			\approx_{m\,\delta_{\mathrm{Line}}^{1/2}}\
1762			\E_{(\ell,\ell_X,\ell_Z) \sim D}\
1763			\E_{(x,z,\alpha,\beta) \in \ell}
1764			&\sum_{f_X,f_Z} \bra{\hat\psi}
1765			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1766			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)}
1767			\big)_{\mathsf{B}\mathsf{A}''}
1768			\ket{\hat\psi}\,,
1769		\end{align*}
1770		where $\delta_{\mathrm{Line}}$ is the error function of
1771		Lemma~\ref{lem:qld-comm-line-cons}.
1772	\end{lemma}
1773	\begin{proof}
1774		\uses{lem:qld-comm-line-cons, lem:qld-sublines, lem:qld-xz-lines,
1775			lem:restricted-line-mixture-bounds, def:ith-restricted-line,
1776			def:expanded-line-measurement}
1777		By Cauchy--Schwarz, the difference of the two sides is bounded by the
1778		square root of the deficit
1779		\[
1780			1 - \E_{(\ell,\ell_X,\ell_Z) \sim D}\
1781			\E_{(x,z,\alpha,\beta) \in \ell} \sum_{a}
1782			\bra{\hat\psi}
1783			T^{\ell_X,\ell_Z,x}_{a} \ot
1784			\hat{M}^{(\mathrm{Point},X),x}_{a}
1785			\ket{\hat\psi}\,,
1786			\qquad
1787			T^{\ell_X,\ell_Z,x}_{a}
1788			= \sum_{f_X,f_Z \,:\, f_X(x)=a}
1789			T^{\ell_X,\ell_Z}_{f_X,f_Z}\,.
1790		\]
1791		By the sandwich definition of $T$ and the projectivity of the lines
1792		measurement $\{\hat{M}^{(\mathrm{Line},X),\ell_X}_{f_X}\}$, the
1793		subtracted expectation equals
1794		$\E \sum_a \bra{\hat\psi}
1795		\hat{M}^{(\mathrm{Line},X),\ell_X}_{[\mathrm{eval}_x(\cdot)=a]} \ot
1796		\hat{M}^{(\mathrm{Point},X),x}_{a} \ket{\hat\psi}$,
1797		which by Property~2 of Lemma~\ref{lem:qld-sublines} is a mixture of the
1798		corresponding averages over the restricted distributions
1799		$D_{\mathrm{v},i}$. By the error inflation of
1800		Lemma~\ref{lem:restricted-line-mixture-bounds} applied to the
1801		line--point consistency in item~3 of Lemma~\ref{lem:qld-comm-line-cons},
1802		each restricted term has deficit $O(m\,\delta_{\mathrm{Line}})$, so the
1803		total deficit is $O(m^2\,\delta_{\mathrm{Line}})$ (the final line of the
1804		source proof asserts this bound for the consistency term itself rather
1805		than for its deficit; see Remark~\ref{rem:qld-4-13-source-defects}).
1806		Taking the square root gives the claimed error
1807		$m\,\delta_{\mathrm{Line}}^{1/2}$.
1808	\end{proof}
