1820			\sum_{f_X,f_Z} \bra{\hat\psi}
1821			\big(T^{\ell_X,\ell_Z}_{f_X,f_Z}\big)_{\mathsf{A}\mathsf{A}'} \ot
1822			\big(\hat{M}^{(\mathrm{Point},Z),z}_{f_Z(z)}
1823			\big)_{\mathsf{B}\mathsf{A}''}
